widget.solution:
def is_group(elements, op):
    S = list(elements)
    for a in S:
        for b in S:
            if op(a, b) not in S:
                return False
    for a in S:
        for b in S:
            for c in S:
                if op(op(a, b), c) != op(a, op(b, c)):
                    return False
    ids = [e for e in S if all(op(e, x) == x and op(x, e) == x for x in S)]
    if not ids:
        return False
    e = ids[0]
    for a in S:
        if not any(op(a, b) == e and op(b, a) == e for b in S):
            return False
    return True
